// Generates src/sim/identity.generated.ts: a runtime identity bound to the simulation source and
// the exact installed @series-inc/rundot-syncplay version. Re-run after ANY change to the listed
// modules or after bumping the syncplay dependency:  npm run gen:identity
import { readFileSync, writeFileSync } from 'node:fs';
import { deriveCustomRuntimeIdentity, kinetixRuntimeModuleManifest } from '@series-inc/rundot-syncplay/core';

// The generated file must NOT appear in its own module list.
const RUNTIME_MODULES = ['sim/game.ts', 'sim/parts.ts', 'sim/track.ts', 'sim/runtime.ts', 'sim/input-codec.ts'];

const syncplayVersion = JSON.parse(
  readFileSync('node_modules/@series-inc/rundot-syncplay/package.json', 'utf8'),
).version as string;

const identity = deriveCustomRuntimeIdentity({
  tickRate: 30,
  inputSchema: { id: 'frankenrun-input/v1' },
  stateSchema: { id: 'frankenrun-state/v1' },
  deterministicVersion: `frankenrun@1+syncplay${syncplayVersion}`,
  runtimeModules: kinetixRuntimeModuleManifest('src', RUNTIME_MODULES),
});

const out = `// GENERATED by scripts/gen-identity.ts — do not edit. Run \`npm run gen:identity\`.
import type { KinetixRuntimeIdentity } from '@series-inc/rundot-syncplay/core/runtime';

export const runtimeIdentity: Readonly<KinetixRuntimeIdentity> = ${JSON.stringify(identity, null, 2)};
`;
writeFileSync('src/sim/identity.generated.ts', out);
console.log(`identity generated (syncplay ${syncplayVersion}), modules: ${RUNTIME_MODULES.length}`);
